import socket,urllib.request,urllib.error,http.client,json
host="tumblr.hentaigay.org"
print("ACTION=TUMBLR_PUBLIC_INGRESS_READ_ONLY")
try:
 addresses=socket.getaddrinfo(host,443)
 print("DNS=RESOLVED" if addresses else "DNS=EMPTY")
except Exception as e: print("DNS=ERROR_"+type(e).__name__)
for label,path in (("PUBLIC_HEALTH","/healthz"),("PUBLIC_LOGIN","/login")):
 try:
  req=urllib.request.Request("https://"+host+path,headers={"User-Agent":"GACE-Diagnostic/1.0"})
  with urllib.request.urlopen(req,timeout=9) as res:
   print(label+"=HTTP_"+str(res.status))
 except urllib.error.HTTPError as e: print(label+"=HTTP_"+str(e.code))
 except Exception as e: print(label+"=ERROR_"+type(e).__name__)
try:
 conn=http.client.HTTPConnection("127.0.0.1",8081,timeout=6)
 conn.request("GET","/healthz"); response=conn.getresponse(); print("LOCAL_HEALTH=HTTP_"+str(response.status)); conn.close()
except Exception as e: print("LOCAL_HEALTH=ERROR_"+type(e).__name__)
